def largest_smallest_integers(lst):
    has_neg = False
    has_pos = False
    largest_neg = None
    smallest_pos = None

    for x in lst:
        if x < 0:
            if not has_neg or x > largest_neg:
                largest_neg = x
                has_neg = True
        elif x > 0:
            if not has_pos or x < smallest_pos:
                smallest_pos = x
                has_pos = True

    return (largest_neg if has_neg else None,
            smallest_pos if has_pos else None)
